import Auth from"./Auth.jsx";

const nav=[
 ["Vue d’ensemble",LayoutDashboard],
 ["Messages",MessageSquare],
 ["Contacts",Users],
 ["Automatisations",Zap],
 ["API & intégrations",KeyRound],
 ["Modèles",FileText],
 ["Statistiques",BarChart3],
 ["Facturation",CreditCard],
];
const publicRoutes=["/","/fonctionnalites","/comment-ca-marche","/tarifs","/region"];

function Logo({large=false}){return <div className={"brand "+(large?"large":"")}><div className="brandMark">➤</div><div><strong>WhatSend <span>Pro</span></strong><small>WhatsApp professionnel, simplement.</small></div></div>}

function go(path){window.history.pushState({}, "", path);window.dispatchEvent(new PopStateEvent("popstate"));window.scrollTo({top:0,behavior:"smooth"})}
function getPath(){return window.location.pathname.replace(/\/+$/,"")||"/"}

function Landing({onAuth}){
 const path=getPath();
 const [route,setRoute]=useState(path);
 useEffect(()=>{const f=()=>setRoute(getPath());window.addEventListener("popstate",f);return()=>window.removeEventListener("popstate",f)},[]);
 const page=route==="/fonctionnalites"?"features":route==="/comment-ca-marche"?"how":route==="/tarifs"?"pricing":route==="/region"?"region":"home";
 const link=(label,p)=><button className={page===p?"landingNavLink active":"landingNavLink"} onClick={()=>go(p==="home"?"/":"/"+({features:"fonctionnalites",how:"comment-ca-marche",pricing:"tarifs",region:"region"}[p]))}>{label}</button>;
 return <div className="landing">
  <header className="landingNav"><Logo/><div className="landingLinks">{link("Fonctionnalités","features")}{link("Comment ça marche","how")}{link("Tarifs","pricing")}{link("Afrique de l’Ouest","region")}</div><button className="navLogin" onClick={()=>onAuth("login")}>Se connecter</button><button className="primary" onClick={()=>onAuth("signup")}>Créer mon compte <ArrowUpRight size={15}/></button></header>
  {page==="home"&&<><section className="landingHero"><div className="heroCopy"><div className="eyebrow">OUTIL PROFESSIONNEL POUR WHATSAPP BUSINESS</div><h1>WhatsApp professionnel.<br/><span>Simple. Connecté. Automatisé.</span></h1><p>WhatSend Pro simplifie l’utilisation professionnelle de WhatsApp Business : conversations, contacts, modèles, automatisations, API, webhooks, statistiques et suivi d’usage dans un seul espace.</p><div className="landingCtas"><button className="primary big" onClick={()=>onAuth("signup")}>Commencer gratuitement <ArrowUpRight size={17}/></button><button className="ghost big" onClick={()=>go("/fonctionnalites")}>Découvrir la plateforme <ChevronRight size={17}/></button></div><div className="trust"><CheckCircle2 size={15}/> Utilisation des mécanismes officiels WhatsApp Business / Meta <span/><ShieldCheck size={15}/> WhatSend Pro n’est pas WhatsApp</div></div><div className="landingVisual"><div className="phone"><div className="phoneTop"><span>WhatSend Pro</span><span className="online">● Connecté</span></div><div className="chat"><div className="bubble in">Bonjour Awa 👋<small>09:41</small></div><div className="bubble out">Bonjour ! Votre commande est confirmée. ✓✓<small>09:42</small></div><div className="bubble in">Merci beaucoup !<small>09:42</small></div></div><div className="phoneBottom">Écrire un message… <Send size={15}/></div></div><div className="floatCard"><Zap size={16}/><div><b>Automatisation active</b><small>Commande confirmée</small></div><CheckCircle2 size={17}/></div></div></section><section className="landingProof"><div><b>1 espace</b><span>Pour piloter votre activité WhatsApp Business.</span></div><div><b>API + Webhooks</b><span>Pour connecter site, CRM, ERP et applications.</span></div><div><b>No-code</b><span>Pour automatiser sans développement.</span></div><div><b>FR / EN</b><span>Pour accompagner l’ouverture régionale.</span></div></section><section className="featureSection"><div className="sectionTitle"><span>UNE PLATEFORME COMPLÈTE</span><h2>Tout ce qu’il faut pour professionnaliser vos échanges</h2><p>WhatSend Pro adapte les mécanismes officiels à un environnement plus simple à utiliser au quotidien.</p></div><div className="featureGrid">{[["Messages","Centralisez les conversations et envoyez depuis votre numéro connecté."],["Contacts","Organisez contacts, tags et historique."],["Automatisations","Déclencheurs et actions sans code."],["API & intégrations","Connectez vos outils métier."],["Modèles","Préparez vos modèles de messages."],["Statistiques","Suivez volumes, statuts et usage."]].map(([t,d],i)=>{const I=[MessageSquare,Users,Zap,Plug,FileText,BarChart3][i];return <div className="featureCard" key={t}><div className="featureIcon"><I size={20}/></div><h3>{t}</h3><p>{d}</p><ChevronRight size={16}/></div>})}</div><button className="sectionCta primary" onClick={()=>go("/fonctionnalites")}>Voir toutes les fonctionnalités <ArrowUpRight size={16}/></button></section><section className="howSection"><div className="sectionTitle"><span>PARCOURS SIMPLE</span><h2>Créer → Connecter → Configurer → Utiliser</h2><p>Un parcours construit autour du compte entreprise et du numéro WhatsApp Business de l’entreprise.</p></div><div className="steps">{[["01","Créer votre espace","Inscrivez votre entreprise et accédez immédiatement au dashboard."],["02","Connecter votre numéro","Lancez le parcours prévu par WhatsApp Business / Meta."],["03","Configurer vos outils","Contacts, modèles, automatisations, API, webhooks et préférences."],["04","Piloter","Messages, statistiques, consommation et facturation depuis le même espace."]].map(x=><div className="step" key={x[0]}><b>{x[0]}</b><h3>{x[1]}</h3><p>{x[2]}</p></div>)}</div></section><section className="officialSection"><div className="officialBadge"><ShieldCheck size={28}/></div><div><span>POSITIONNEMENT OFFICIEL</span><h2>Une couche de simplification autour de WhatsApp Business.</h2><p>WhatSend Pro n’est pas WhatsApp et ne se présente pas comme une filiale de Meta. Le produit est conçu pour simplifier et adapter l’utilisation des mécanismes officiels de WhatsApp Business Platform / Meta aux besoins des entreprises.</p></div><div className="officialNote"><b>Partenaire officiel</b><span>Cette mention n’est utilisée que si le statut correspondant est effectivement accordé à WhatSend Pro.</span></div></section></>}
  {page==="features"&&<LandingFeatures onAuth={onAuth}/>}
  {page==="how"&&<LandingHow onAuth={onAuth}/>}
  {page==="pricing"&&<LandingPricing onAuth={onAuth}/>}
  {page==="region"&&<LandingRegion onAuth={onAuth}/>}
  <footer className="landingFooter"><Logo/><span>© 2026 WhatSend Pro</span><span>Outil professionnel pour simplifier WhatsApp Business.</span><button onClick={()=>go("/fonctionnalites")}>Fonctionnalités</button><button onClick={()=>go("/tarifs")}>Tarifs</button></footer>
 </div>
}

function LandingFeatures({onAuth}){const f=[["Messages","Boîte de réception professionnelle","Centralisez les conversations et recherchez rapidement vos échanges."],["Contacts","Carnet exploitable","Ajoutez, modifiez, recherchez et segmentez vos contacts."],["Automatisations","Scénarios sans code","Déclenchez des actions sur événement, mot-clé ou intégration."],["Modèles","Messages structurés","Préparez les contenus nécessaires aux modèles WhatsApp Business."],["API","Votre WhatsApp dans vos applications","Reliez site, CRM, ERP ou application métier."],["Webhooks","Événements en temps réel","Recevez les statuts et événements disponibles."],["Statistiques","Une vision claire","Volumes, livraisons et usage depuis le dashboard."],["Facturation","Consommation lisible","Visualisez l’usage et les éléments de facturation disponibles."]];return <main className="landingPage"><div className="landingPageHero"><span>FONCTIONNALITÉS</span><h1>Une plateforme de simplification pour WhatsApp Business.</h1><p>Le produit est organisé autour des besoins opérationnels des entreprises, sans se présenter comme WhatsApp lui-même.</p><button className="primary big" onClick={()=>onAuth("signup")}>Créer mon espace <ArrowUpRight size={16}/></button></div><div className="featureDetailGrid">{f.map(([a,b,c],i)=>{const I=[MessageSquare,Users,Zap,FileText,Plug,Webhook,BarChart3,CreditCard][i];return <article className="featureDetail" key={a}><div className="featureIcon"><I size={22}/></div><span>{a}</span><h3>{b}</h3><p>{c}</p></article>})}</div><div className="darkCallout"><h2>Pour entreprises, agences, startups et développeurs.</h2><p>Un socle commun pour utiliser, automatiser et intégrer WhatsApp Business avec une interface plus simple.</p><button className="primary" onClick={()=>onAuth("signup")}>Commencer gratuitement</button></div></main>}

function LandingHow({onAuth}){const s=[["01","Créer le compte","E-mail, mot de passe et informations de l’entreprise."],["02","Connecter le numéro","Parcours officiel WhatsApp Business / Meta pour rattacher le numéro de l’entreprise."],["03","Configurer le profil","Informations de l’entreprise, langue, notifications et paramètres."],["04","Construire les automatisations","Déclencheurs, conditions et actions."],["05","Connecter vos outils","Clés API et webhooks pour site, CRM, ERP ou application."],["06","Piloter","Conversations, statistiques, consommation et facturation."]];return <main className="landingPage"><div className="landingPageHero"><span>COMMENT ÇA MARCHE</span><h1>Un parcours professionnel, étape par étape.</h1><p>WhatSend Pro sert de couche de simplification : le numéro et les ressources WhatsApp restent rattachés à l’entreprise et aux mécanismes officiels.</p></div><div className="howTimeline">{s.map(x=><article className="timelineStep" key={x[0]}><b>{x[0]}</b><div><h3>{x[1]}</h3><p>{x[2]}</p></div></article>)}</div><div className="complianceGrid"><div><ShieldCheck size={22}/><h3>Usage conforme</h3><p>Les règles, consentements et exigences applicables à WhatsApp Business restent applicables.</p></div><div><Plug size={22}/><h3>Architecture ouverte</h3><p>API et webhooks permettent de relier les systèmes existants.</p></div><div><Lock size={22}/><h3>Séparation des accès</h3><p>Les données sont isolées par compte grâce à Supabase Auth et aux politiques RLS.</p></div></div><button className="primary big" onClick={()=>onAuth("signup")}>Créer mon espace <ArrowUpRight size={16}/></button></main>}

function LandingPricing({onAuth}){return <main className="landingPage"><div className="landingPageHero"><span>TARIFS</span><h1>Commencer, utiliser, évoluer.</h1><p>WhatSend Pro distingue les fonctionnalités de plateforme et les coûts liés à l’utilisation des services WhatsApp/Meta.</p></div><div className="pricingCards"><article className="pricingPlan"><span>01</span><h3>Free</h3><strong>0 FCFA</strong><small>Découvrir la plateforme</small><ul><li>Création du compte</li><li>Dashboard</li><li>Configuration initiale</li><li>Accès aux modules</li></ul><button className="primary" onClick={()=>onAuth("signup")}>Commencer</button></article><article className="pricingPlan featuredPlan"><span>02</span><h3>Usage</h3><strong>Selon l’usage</strong><small>Pour les entreprises actives</small><ul><li>Suivi de consommation</li><li>Fonctions selon l’offre</li><li>API et webhooks</li><li>Automatisations</li></ul><button className="primary" onClick={()=>onAuth("signup")}>Démarrer</button></article><article className="pricingPlan"><span>03</span><h3>Premium</h3><strong>Sur offre</strong><small>Besoins avancés</small><ul><li>Fonctionnalités avancées</li><li>Équipe et accès</li><li>Automatisations avancées</li><li>Accompagnement selon l’offre</li></ul><button className="secondary" onClick={()=>onAuth("signup")}>Nous contacter</button></article></div><div className="pricingNote"><b>Important</b><span>Les coûts et règles de WhatsApp/Meta sont distincts des éventuels frais WhatSend Pro.</span></div></main>}

function LandingRegion({onAuth}){const c=[["🇨🇮","Côte d’Ivoire","Abidjan"],["🇸🇳","Sénégal","Dakar"],["🇧🇯","Bénin","Cotonou"],["🇹🇬","Togo","Lomé"],["🇬🇭","Ghana","Accra"],["🇳🇬","Nigéria","Abuja"],["🇬🇳","Guinée","Conakry"],["🇬🇼","Guinée-Bissau","Bissau"],["🇱🇷","Libéria","Monrovia"],["🇸🇱","Sierra Leone","Freetown"],["🇬🇲","Gambie","Banjul"],["🇨🇻","Cabo Verde","Praia"]];return <main className="landingPage"><div className="landingPageHero"><span>AFRIQUE DE L’OUEST</span><h1>Un produit pensé depuis la Côte d’Ivoire pour évoluer dans la région.</h1><p>WhatSend Pro commence avec une approche francophone et une architecture capable d’accompagner progressivement les entreprises d’Afrique de l’Ouest.</p></div><div className="regionBanner"><Globe size={30}/><div><b>CEDEAO</b><span>Une présence régionale pensée progressivement, sans présenter une couverture commerciale qui n’existe pas encore.</span></div></div><div className="countryGrid">{c.map(x=><article className="countryCard" key={x[1]}><span className="flag">{x[0]}</span><div><b>{x[1]}</b><small>{x[2]}</small></div></article>)}</div><div className="darkCallout"><h2>Français aujourd’hui. Multilingue demain.</h2><p>Le dashboard est structuré pour le français et l’anglais, avec une ouverture progressive à d’autres marchés.</p><button className="primary" onClick={()=>onAuth("signup")}>Créer mon compte</button></div></main>}

function Toast({toast,onClose}){if(!toast)return null;return <div className={"toast "+toast.type}><span>{toast.type==="error"?<AlertCircle size={16}/>:<CheckCircle2 size={16}/>}</span><div>{toast.text}</div><button onClick={onClose}><X size={15}/></button></div>}

function Modal({title,onClose,children}){return <div className="modal"><div className="modalCard"><div className="modalHead"><h3>{title}</h3><button className="iconBtn" onClick={onClose}><X size={16}/></button></div>{children}</div></div>}

function useToast(){const[toast,setToast]=useState(null);const show=(text,type="success")=>{setToast({text,type});setTimeout(()=>setToast(null),4200)};return{toast,show,clear:()=>setToast(null)}}

function Dashboard({user,onLogout}){
 const[active,setActive]=useState("Vue d’ensemble"),[mobile,setMobile]=useState(false),[profile,setProfile]=useState(null),[account,setAccount]=useState(null);
 const{toast,show,clear}=useToast();const name=profile?.full_name||user?.user_metadata?.company_name||user?.email?.split("@")[0]||"Compte";
 useEffect(()=>{let live=true;(async()=>{if(!supabase||!user)return;let{data}=await supabase.from("profiles").select("*").eq("id",user.id).maybeSingle();if(!data){const r=await supabase.from("profiles").insert({id:user.id,full_name:user.user_metadata?.full_name||"",company_name:user.user_metadata?.company_name||"",language:"fr"}).select("*").single();data=r.data}if(live)setProfile(data||null);const a=await supabase.from("whatsapp_accounts").select("*").eq("user_id",user.id).order("created_at",{ascending:false}).limit(1).maybeSingle();if(live)setAccount(a.data||null)})();return()=>{live=false}},[user]);
 const open=(x)=>{setActive(x);setMobile(false);window.scrollTo({top:0,behavior:"smooth"})};
 let content=<Overview user={user} account={account} open={open}/>;
 if(active==="Messages")content=<Messages user={user} account={account} show={show}/>;
 if(active==="Contacts")content=<Contacts user={user} show={show}/>;
 if(active==="Automatisations")content=<Automations user={user} show={show}/>;
 if(active==="API & intégrations")content=<Integrations user={user} show={show}/>;
 if(active==="Modèles")content=<Templates user={user} show={show}/>;
 if(active==="Statistiques")content=<Analytics user={user} account={account}/>;
 if(active==="Facturation")content=<Billing user={user} show={show}/>;
 if(active==="Paramètres")content=<SettingsPage user={user} profile={profile} setProfile={setProfile} account={account} setAccount={setAccount} show={show}/>;
 return <><div className="app"><aside className={"sidebar "+(mobile?"open":"")}><Logo/><div className="workspace"><span className="dot"/><div><b>{profile?.company_name||"Mon espace"}</b><small>Compte professionnel</small></div><ChevronRight size={15}/></div><nav>{nav.map(([label,I])=><button className={active===label?"active":""} onClick={()=>open(label)} key={label}><I size={18}/><span>{label}</span></button>)}</nav><div className="sidebarBottom"><button className={active==="Paramètres"?"active":""} onClick={()=>open("Paramètres")}><Settings size={18}/>Paramètres</button><button onClick={onLogout}><LogOut size={18}/>Déconnexion</button><div className="user"><div className="avatar">{name.slice(0,2).toUpperCase()}</div><div><b>{name}</b><small>{user.email}</small></div></div></div></aside><main className="dashboardMain"><header className="topbar"><div className="headTitle"><button className="mobileMenu" onClick={()=>setMobile(!mobile)}><Menu size={20}/></button><div><div className="eyebrow">ESPACE PROFESSIONNEL</div><h1>{active}</h1></div></div><div className="headerActions"><div className="search"><Search size={17}/><input placeholder="Rechercher…" onChange={e=>{if(e.target.value.length>1)show("La recherche globale sera étendue à tous les modules.","success")}}/></div><button className="iconBtn" onClick={()=>show("Aucune nouvelle notification.","success")}><Bell size={18}/></button><div className="profile">{name.slice(0,2).toUpperCase()}</div></div></header><div className="dashboardContent">{content}</div><footer>© 2026 WhatSend Pro · Outil professionnel pour simplifier WhatsApp Business.</footer></main></div><Toast toast={toast} onClose={clear}/></>
}

function Page({title,eyebrow,action,children}){return <><header className="pageHeader"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1></div>{action}</header>{children}</>}

function Overview({user,account,open}){const[stats,setStats]=useState({messages:0,inbound:0,contacts:0,autos:0});const[loading,setLoading]=useState(true);useEffect(()=>{let live=true;(async()=>{if(!supabase)return;const [m,c,a]=await Promise.all([supabase.from("messages").select("direction",{count:"exact",head:true}).eq("user_id",user.id),supabase.from("contacts").select("id",{count:"exact",head:true}).eq("user_id",user.id),supabase.from("automations").select("id",{count:"exact",head:true}).eq("user_id",user.id).eq("enabled",true)]);if(live)setStats({messages:m.count||0,inbound:0,contacts:c.count||0,autos:a.count||0});setLoading(false)})();return()=>{live=false}},[user]);return <><section className="hero dashboardHero"><div><span className="pill"><span className="greenDot"/> Compte sécurisé</span><h2>Bonjour, bienvenue sur <em>WhatSend Pro</em>.</h2><p>Un espace conçu pour simplifier l’utilisation de WhatsApp Business de votre entreprise.</p><div className="heroActions"><button className="primary" onClick={()=>open("Messages")}><Send size={16}/> Nouveau message</button><button className="secondary" onClick={()=>open("Automatisations")}><Plus size={16}/> Créer une automatisation</button></div></div><button className="connection" onClick={()=>open("Paramètres")}><div className="connectionIcon"><Smartphone size={17}/></div><div><small>PROCHAINE ÉTAPE</small><strong>{account?.status==="connected"?"WhatsApp Business connecté":"Connecter WhatsApp Business"}</strong><span>{account?.status==="connected"?"Numéro actif":"Parcours officiel Meta"}</span></div><ArrowUpRight size={17}/></button></section><div className="stats">{[["Messages",loading?"…":stats.messages,""],["Contacts",loading?"…":stats.contacts,""],["Automatisations actives",loading?"…":stats.autos,""],["WhatsApp",account?.status==="connected"?"Connecté":"À connecter",""]].map(x=><div className="stat" key={x[0]}><span>{x[0]}</span><strong>{x[1]}</strong><small>{x[2]}</small></div>)}</div><section className="grid"><div className="card large"><div className="cardHead"><div><h3>Activité des messages</h3><p>Les données réelles apparaissent après connexion et utilisation.</p></div><button className="filterBtn" onClick={()=>open("Statistiques")}>Voir les statistiques</button></div><div className="emptyChart"><BarChart3 size={30}/><b>{stats.messages?"Activité enregistrée":"Aucune activité pour le moment"}</b><span>{stats.messages?"Consultez le module Statistiques pour le détail.":"Connectez votre numéro WhatsApp Business pour commencer."}</span></div></div><div className="card"><div className="cardHead"><div><h3>Accès rapide</h3><p>Actions fréquentes</p></div></div><div className="quickList"><button onClick={()=>open("Contacts")}><Users size={17}/><span>Gérer les contacts</span><ChevronRight size={15}/></button><button onClick={()=>open("Modèles")}><FileText size={17}/><span>Créer un modèle</span><ChevronRight size={15}/></button><button onClick={()=>open("API & intégrations")}><KeyRound size={17}/><span>Configurer l’API</span><ChevronRight size={15}/></button></div></div></section></>}

function Messages({user,account,show}){const[contacts,setContacts]=useState([]),[messages,setMessages]=useState([]),[selected,setSelected]=useState(null),[text,setText]=useState(""),[search,setSearch]=useState(""),[loading,setLoading]=useState(true),[sending,setSending]=useState(false);
 const load=async()=>{if(!supabase)return;setLoading(true);const[c,m]=await Promise.all([supabase.from("contacts").select("*").eq("user_id",user.id).order("created_at",{ascending:false}),supabase.from("messages").select("*").eq("user_id",user.id).order("created_at",{ascending:true}).limit(200)]);setContacts(c.data||[]);setMessages(m.data||[]);setLoading(false);if(!selected&&c.data?.length)setSelected(c.data[0])};useEffect(()=>{load()},[user]);
 const filtered=contacts.filter(c=>(c.name||"").toLowerCase().includes(search.toLowerCase())||(c.phone_number||"").includes(search));const convo=messages.filter(m=>selected&&(m.contact_id===selected.id||m.body?.includes(selected.phone_number)));
 async function send(){if(!selected||!text.trim())return;if(!account||account.status!=="connected"){show("Connectez d’abord votre numéro WhatsApp Business dans Paramètres.","error");return}setSending(true);const r=await supabase.functions.invoke("whatsapp-send",{body:{account_id:account.id,to:selected.phone_number,message:text.trim()}});setSending(false);if(r.error||r.data?.error){show(r.data?.error||r.error?.message||"Envoi impossible.","error");return}setText("");show("Message envoyé.");load()}
 return <Page title="Messages" eyebrow="CONVERSATIONS"><div className="messagesLayout"><div className="conversationList"><div className="listSearch"><Search size={16}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Rechercher une conversation…"/></div>{loading?<div className="emptyState">Chargement…</div>:filtered.length?filtered.map(c=><button className={"conversation "+(selected?.id===c.id?"selected":"")} key={c.id} onClick={()=>setSelected(c)}><div className="avatar">{(c.name||c.phone_number).slice(0,2).toUpperCase()}</div><div><b>{c.name||"Sans nom"}</b><small>{c.phone_number}</small></div><ChevronRight size={14}/></button>):<div className="emptyState"><Users size={25}/><b>Aucun contact</b><span>Ajoutez un contact pour démarrer.</span></div>}</div><div className="conversationPanel">{selected?<><div className="conversationHeader"><div><b>{selected.name||"Sans nom"}</b><small>{selected.phone_number}</small></div><button className="iconBtn" onClick={()=>show("Fiche contact : "+(selected.name||selected.phone_number))}><Users size={16}/></button></div><div className="chatArea">{convo.length?convo.map(m=><div className={"bubble "+(m.direction==="outbound"?"out":"in")} key={m.id}>{m.body||"[message]"}<small>{new Date(m.created_at).toLocaleTimeString("fr-FR",{hour:"2-digit",minute:"2-digit"})}</small></div>):<div className="emptyState"><MessageSquare size={28}/><b>Aucun message</b><span>Écrivez votre premier message à ce contact.</span></div>}</div><div className="composer"><input value={text} onChange={e=>setText(e.target.value)} onKeyDown={e=>{if(e.key==="Enter"&&!e.shiftKey){e.preventDefault();send()}}} placeholder="Écrire un message…"/><button className="primary" disabled={sending} onClick={send}>{sending?<RefreshCw className="spin" size={16}/>:<Send size={16}/>}</button></div></>:<div className="emptyState"><MessageSquare size={30}/><b>Sélectionnez une conversation</b><span>Les conversations de votre compte apparaîtront ici.</span></div>}</div></div></Page>}

function Contacts({user,show}){const[rows,setRows]=useState([]),[open,setOpen]=useState(false),[editing,setEditing]=useState(null),[form,setForm]=useState({name:"",phone_number:"",email:""}),[search,setSearch]=useState(""),[loading,setLoading]=useState(true);
 const load=async()=>{setLoading(true);const r=await supabase.from("contacts").select("*").eq("user_id",user.id).order("created_at",{ascending:false});setRows(r.data||[]);setLoading(false)};useEffect(()=>{load()},[user]);
 const save=async e=>{e.preventDefault();const payload={name:form.name.trim(),phone_number:form.phone_number.trim(),email:form.email.trim()||null};const r=editing?await supabase.from("contacts").update(payload).eq("id",editing).eq("user_id",user.id):await supabase.from("contacts").insert({...payload,user_id:user.id,tags:[]});if(r.error){show(r.error.message,"error");return}setOpen(false);setEditing(null);setForm({name:"",phone_number:"",email:""});show(editing?"Contact modifié.":"Contact ajouté.");load()};
 const remove=async id=>{if(!confirm("Supprimer ce contact ?"))return;const r=await supabase.from("contacts").delete().eq("id",id).eq("user_id",user.id);if(r.error)show(r.error.message,"error");else{show("Contact supprimé.");load()}};const filtered=rows.filter(c=>(c.name||"").toLowerCase().includes(search.toLowerCase())||(c.phone_number||"").includes(search));return <Page title="Contacts" eyebrow="CARNET DE CONTACTS" action={<button className="primary" onClick={()=>{setEditing(null);setForm({name:"",phone_number:"",email:""});setOpen(true)}}><Plus size={16}/> Ajouter un contact</button>}>{open&&<Modal title={editing?"Modifier le contact":"Nouveau contact"} onClose={()=>setOpen(false)}><form onSubmit={save}><label className="field">Nom<input value={form.name} onChange={e=>setForm({...form,name:e.target.value})} required/></label><label className="field">Téléphone<input value={form.phone_number} onChange={e=>setForm({...form,phone_number:e.target.value})} required placeholder="+225..."/></label><label className="field">E-mail<input value={form.email} onChange={e=>setForm({...form,email:e.target.value})} type="email"/></label><button className="primary full"><Save size={15}/> Enregistrer</button></form></Modal>}<div className="tableCard"><div className="tableToolbar"><div className="listSearch"><Search size={16}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Rechercher un contact…"/></div><span className="countBadge">{rows.length} contact{rows.length>1?"s":""}</span></div><table><thead><tr><th>Contact</th><th>Téléphone</th><th>E-mail</th><th>Tags</th><th>Actions</th></tr></thead><tbody>{loading?<tr><td colSpan="5">Chargement…</td></tr>:filtered.length?filtered.map(c=><tr key={c.id}><td><div className="tablePerson"><div className="avatar">{(c.name||c.phone_number).slice(0,2).toUpperCase()}</div><b>{c.name||"Sans nom"}</b></div></td><td>{c.phone_number}</td><td>{c.email||"—"}</td><td>{c.tags?.length?c.tags.join(", "):"—"}</td><td><div className="rowActions"><button onClick={()=>{setEditing(c.id);setForm({name:c.name||"",phone_number:c.phone_number||"",email:c.email||""});setOpen(true)}}><Edit3 size={14}/></button><button onClick={()=>remove(c.id)}><Trash2 size={14}/></button></div></td></tr>):<tr><td colSpan="5">Aucun contact. Ajoutez votre premier contact.</td></tr>}</tbody></table></div></Page>}

function Automations({user,show}){const[items,setItems]=useState([]),[open,setOpen]=useState(false),[editing,setEditing]=useState(null),[form,setForm]=useState({name:"",trigger_type:"new_contact",action:"send_message"});const load=async()=>{const r=await supabase.from("automations").select("*").eq("user_id",user.id).order("created_at",{ascending:false});setItems(r.data||[])};useEffect(()=>{load()},[user]);const save=async e=>{e.preventDefault();const payload={name:form.name,trigger_type:form.trigger_type,trigger_config:{},action_config:{type:form.action},enabled:false,updated_at:new Date().toISOString()};const r=editing?await supabase.from("automations").update(payload).eq("id",editing).eq("user_id",user.id):await supabase.from("automations").insert({...payload,user_id:user.id});if(r.error){show(r.error.message,"error");return}setOpen(false);setEditing(null);show(editing?"Automatisation modifiée.":"Automatisation créée.");load()};const toggle=async a=>{const r=await supabase.from("automations").update({enabled:!a.enabled,updated_at:new Date().toISOString()}).eq("id",a.id).eq("user_id",user.id);if(r.error)show(r.error.message,"error");else load()};const remove=async id=>{if(!confirm("Supprimer cette automatisation ?"))return;await supabase.from("automations").delete().eq("id",id).eq("user_id",user.id);load()};return <Page title="Automatisations" eyebrow="NO-CODE" action={<button className="primary" onClick={()=>{setEditing(null);setForm({name:"",trigger_type:"new_contact",action:"send_message"});setOpen(true)}}><Plus size={16}/> Nouvelle automatisation</button>}>{open&&<Modal title={editing?"Modifier l’automatisation":"Nouvelle automatisation"} onClose={()=>setOpen(false)}><form onSubmit={save}><label className="field">Nom<input value={form.name} onChange={e=>setForm({...form,name:e.target.value})} required placeholder="Ex. Bienvenue nouveau contact"/></label><label className="field">Déclencheur<select value={form.trigger_type} onChange={e=>setForm({...form,trigger_type:e.target.value})}><option value="new_contact">Nouveau contact</option><option value="keyword">Mot-clé</option><option value="api_event">Événement API</option><option value="message_received">Message reçu</option></select></label><label className="field">Action<select value={form.action} onChange={e=>setForm({...form,action:e.target.value})}><option value="send_message">Envoyer un message</option><option value="notify">Notifier l’équipe</option><option value="webhook">Appeler un webhook</option></select></label><button className="primary full">Enregistrer</button></form></Modal>}<div className="automationGrid">{items.length?items.map(a=><div className="automationCard" key={a.id}><div className="autoTop"><div className="autoIcon"><Zap size={18}/></div><button className={a.enabled?"toggle on":"toggle"} onClick={()=>toggle(a)}><span/></button></div><h3>{a.name}</h3><p><b>Déclencheur :</b> {a.trigger_type}</p><p><b>Action :</b> {a.action_config?.type||"À configurer"}</p><div className="autoFoot"><span>{a.enabled?<><CheckCircle2 size={14}/> Active</>:<><Pause size={14}/> Inactive</>}</span><div><button onClick={()=>{setEditing(a.id);setForm({name:a.name,trigger_type:a.trigger_type,action:a.action_config?.type||"send_message"});setOpen(true)}}>Modifier</button><button onClick={()=>remove(a.id)}>Supprimer</button></div></div></div>):<div className="card emptyState"><Zap size={28}/><b>Aucune automatisation</b><span>Créez votre premier scénario.</span></div>}</div></Page>}

async function sha256(value){const b=new TextEncoder().encode(value),h=await crypto.subtle.digest("SHA-256",b);return Array.from(new Uint8Array(h)).map(x=>x.toString(16).padStart(2,"0")).join("")}

function Integrations({user,show}){const[keys,setKeys]=useState([]),[webhook,setWebhook]=useState(""),[open,setOpen]=useState(false),[keyName,setKeyName]=useState(""),[createdKey,setCreatedKey]=useState("");const load=async()=>{const r=await supabase.from("api_keys").select("id,name,key_prefix,last_used_at,created_at").eq("user_id",user.id).order("created_at",{ascending:false});setKeys(r.data||[])};useEffect(()=>{load()},[user]);const createKey=async e=>{e.preventDefault();const raw="ws_live_"+crypto.randomUUID().replaceAll("-","")+crypto.randomUUID().replaceAll("-","");const hash=await sha256(raw);const r=await supabase.from("api_keys").insert({user_id:user.id,name:keyName||"Clé API",key_prefix:raw.slice(0,16),key_hash:hash}).select("id,name,key_prefix,created_at").single();if(r.error){show(r.error.message,"error");return}setCreatedKey(raw);setKeyName("");setOpen(false);load()};const remove=async id=>{if(!confirm("Révoquer cette clé API ?"))return;const r=await supabase.from("api_keys").delete().eq("id",id).eq("user_id",user.id);if(r.error)show(r.error.message,"error");else{show("Clé révoquée.");load()}};const webhookUrl=(window.location.origin+"/api/webhook");return <Page title="API & intégrations" eyebrow="DÉVELOPPEURS"><div className="integrationHero"><div><span className="pill greenPill">API prête</span><h2>Connectez WhatSend Pro à votre écosystème.</h2><p>Les clés API sont personnelles à votre espace. Les secrets Meta restent côté serveur et ne sont jamais exposés dans le navigateur.</p></div><div className="codePreview"><div>POST /functions/v1/whatsapp-send</div><pre>{"Authorization: Bearer ws_live_••••••\\nContent-Type: application/json\\n\\n{\\\"to\\\":\\\"+225...\\\",\\\"message\\\":\\\"Bonjour\\\"}"}</pre></div></div><div className="integrationGrid"><div className="card"><Webhook size={20}/><h3>Webhook</h3><p>Point d’entrée de votre intégration pour recevoir les événements.</p><label className="field">URL<input value={webhook||webhookUrl} onChange={e=>setWebhook(e.target.value)}/></label><button className="secondary" onClick={()=>{navigator.clipboard?.writeText(webhook||webhookUrl);show("URL copiée.")}}><Copy size={14}/> Copier</button></div><div className="card"><KeyRound size={20}/><h3>Clés API</h3><p>Créez, consultez et révoquez les accès de vos applications.</p><button className="primary" onClick={()=>setOpen(true)}><Plus size={14}/> Créer une clé</button></div><div className="card"><FileText size={20}/><h3>Documentation</h3><p>Structure d’appel, authentification et exemples.</p><button className="secondary" onClick={()=>show("Documentation API : utilisez POST avec votre clé Bearer et les données du contact.","success")}>Voir la documentation <ExternalLink size={14}/></button></div></div><div className="tableCard" style={{marginTop:14}}><div className="tableToolbar"><b>Vos clés API</b><span className="countBadge">{keys.length}</span></div><table><thead><tr><th>Nom</th><th>Préfixe</th><th>Dernière utilisation</th><th>Créée</th><th/></tr></thead><tbody>{keys.length?keys.map(k=><tr key={k.id}><td>{k.name}</td><td><code>{k.key_prefix}…</code></td><td>{k.last_used_at?new Date(k.last_used_at).toLocaleString("fr-FR"):"Jamais"}</td><td>{new Date(k.created_at).toLocaleDateString("fr-FR")}</td><td><button className="dangerBtn" onClick={()=>remove(k.id)}>Révoquer</button></td></tr>):<tr><td colSpan="5">Aucune clé API.</td></tr>}</tbody></table></div>{open&&<Modal title="Créer une clé API" onClose={()=>setOpen(false)}><form onSubmit={createKey}><label className="field">Nom<input value={keyName} onChange={e=>setKeyName(e.target.value)} placeholder="Mon application"/></label><button className="primary full">Générer la clé</button></form></Modal>}{createdKey&&<Modal title="Clé API créée" onClose={()=>setCreatedKey("")}><div className="secretBox"><Lock size={17}/><p>Copiez cette clé maintenant. Elle ne sera plus affichée intégralement.</p><code>{createdKey}</code><button className="primary full" onClick={()=>{navigator.clipboard?.writeText(createdKey);show("Clé copiée.");}}>Copier la clé</button></div></Modal>}</Page>}

function Templates({user,show}){const[items,setItems]=useState([]),[open,setOpen]=useState(false),[editing,setEditing]=useState(null),[form,setForm]=useState({name:"",body:"",language:"fr",category:"UTILITY"});const load=async()=>{const r=await supabase.from("templates").select("*").eq("user_id",user.id).order("created_at",{ascending:false});setItems(r.data||[])};useEffect(()=>{load()},[user]);const save=async e=>{e.preventDefault();const payload={name:form.name.trim(),body:form.body,language:form.language,category:form.category,status:"DRAFT",updated_at:new Date().toISOString()};const r=editing?await supabase.from("templates").update(payload).eq("id",editing).eq("user_id",user.id):await supabase.from("templates").insert({...payload,user_id:user.id});if(r.error){show(r.error.message,"error");return}setOpen(false);setEditing(null);show("Modèle enregistré.");load()};const remove=async id=>{if(!confirm("Supprimer ce modèle ?"))return;await supabase.from("templates").delete().eq("id",id).eq("user_id",user.id);load()};return <Page title="Modèles" eyebrow="MESSAGE TEMPLATES" action={<button className="primary" onClick={()=>{setEditing(null);setForm({name:"",body:"",language:"fr",category:"UTILITY"});setOpen(true)}}><Plus size={16}/> Nouveau modèle</button>}>{open&&<Modal title={editing?"Modifier le modèle":"Nouveau modèle"} onClose={()=>setOpen(false)}><form onSubmit={save}><label className="field">Nom<input value={form.name} onChange={e=>setForm({...form,name:e.target.value})} required placeholder="nom_du_modele"/></label><div className="formRow"><label className="field">Langue<select value={form.language} onChange={e=>setForm({...form,language:e.target.value})}><option value="fr">Français</option><option value="en">English</option></select></label><label className="field">Catégorie<select value={form.category} onChange={e=>setForm({...form,category:e.target.value})}><option>UTILITY</option><option>MARKETING</option><option>AUTHENTICATION</option></select></label></div><label className="field">Contenu<textarea value={form.body} onChange={e=>setForm({...form,body:e.target.value})} required placeholder="Bonjour {{1}}…"/></label><button className="primary full">Enregistrer</button></form></Modal>}<div className="templateGrid">{items.length?items.map(t=><div className="templateCard" key={t.id}><div className="templateTop"><span className="tag">{t.category}</span><span className="status">{t.status}</span></div><h3>{t.name}</h3><code>{t.language}</code><p>{t.body}</p><div className="templateFoot"><button onClick={()=>{navigator.clipboard?.writeText(t.body);show("Contenu copié.")}}><Copy size={14}/> Copier</button><button onClick={()=>{setEditing(t.id);setForm({name:t.name,body:t.body,language:t.language,category:t.category});setOpen(true)}}><Edit3 size={14}/> Modifier</button><button onClick={()=>remove(t.id)}><Trash2 size={14}/></button></div></div>):<div className="card emptyState"><FileText size={28}/><b>Aucun modèle</b><span>Créez votre premier modèle.</span></div>}</div></Page>}

function Analytics({user}){const[rows,setRows]=useState([]),[loading,setLoading]=useState(true);useEffect(()=>{(async()=>{const r=await supabase.from("usage_events").select("*").eq("user_id",user.id).order("created_at",{ascending:false}).limit(100);setRows(r.data||[]);setLoading(false)})()},[user]);const sent=rows.filter(x=>/message|send/i.test(x.event_type||"")).reduce((n,x)=>n+(x.quantity||0),0);const amount=rows.reduce((n,x)=>n+Number(x.amount||0),0);return <Page title="Statistiques" eyebrow="ANALYTICS"><div className="stats statsLarge">{[["Événements",rows.length],["Messages",sent],["Usage facturé",amount.toLocaleString("fr-FR")+" FCFA"],["Dernière activité",rows[0]?new Date(rows[0].created_at).toLocaleDateString("fr-FR"):"—"]].map(x=><div className="stat" key={x[0]}><span>{x[0]}</span><strong>{loading?"…":x[1]}</strong></div>)}</div><div className="card chartCard"><div className="cardHead"><div><h3>Activité récente</h3><p>Les indicateurs proviennent des événements enregistrés dans votre espace.</p></div><button className="filterBtn" onClick={()=>window.location.reload()}><RefreshCw size={14}/> Actualiser</button></div>{rows.length?<div className="activityList">{rows.slice(0,12).map(r=><div key={r.id}><span>{r.event_type}</span><b>{r.quantity||1}</b><small>{new Date(r.created_at).toLocaleString("fr-FR")}</small></div>)}</div>:<div className="emptyChart tall"><BarChart3 size={35}/><b>Pas encore de données</b><span>Commencez à utiliser votre compte pour voir l’activité.</span></div>}</div></Page>}

function Billing({user,show}){const[rows,setRows]=useState([]),[loading,setLoading]=useState(true);useEffect(()=>{(async()=>{const r=await supabase.from("usage_events").select("*").eq("user_id",user.id).order("created_at",{ascending:false}).limit(100);setRows(r.data||[]);setLoading(false)})()},[user]);const total=rows.reduce((n,x)=>n+Number(x.amount||0),0);return <Page title="Facturation" eyebrow="USAGE & FACTURATION"><div className="billingGrid"><div className="balanceCard"><span>USAGE ENREGISTRÉ</span><strong>{loading?"…":total.toLocaleString("fr-FR")} <small>FCFA</small></strong><p>Ce montant correspond aux événements de consommation enregistrés pour votre compte.</p><button className="primary" onClick={()=>show("La demande de rechargement peut être traitée par l’équipe WhatSend Pro selon votre offre.","success")}><WalletCards size={16}/> Demander un rechargement</button></div><div className="card"><h3>Modèle tarifaire</h3><p>Les coûts WhatsApp/Meta et les éventuels frais de plateforme sont distingués dans le suivi d’usage.</p><div className="billingLine"><span>Événements</span><b>{rows.length}</b></div><div className="billingLine"><span>Usage enregistré</span><b>{total.toLocaleString("fr-FR")} FCFA</b></div><div className="billingLine"><span>Prochaine facture</span><b>Selon l’offre</b></div></div></div><div className="tableCard" style={{marginTop:14}}><div className="tableToolbar"><b>Historique d’usage</b></div><table><thead><tr><th>Date</th><th>Événement</th><th>Quantité</th><th>Montant</th></tr></thead><tbody>{rows.length?rows.map(r=><tr key={r.id}><td>{new Date(r.created_at).toLocaleString("fr-FR")}</td><td>{r.event_type}</td><td>{r.quantity}</td><td>{Number(r.amount||0).toLocaleString("fr-FR")} {r.currency||"XOF"}</td></tr>):<tr><td colSpan="4">Aucun événement de facturation.</td></tr>}</tbody></table></div></Page>}

function SettingsPage({user,profile,setProfile,account,setAccount,show}){const[p,setP]=useState({full_name:profile?.full_name||"",company_name:profile?.company_name||"",language:profile?.language||"fr"});const[a,setA]=useState({display_name:account?.display_name||"",phone_number:account?.phone_number||"",phone_number_id:account?.phone_number_id||"",business_account_id:account?.business_account_id||"",status:account?.status||"pending"});useEffect(()=>{setP({full_name:profile?.full_name||"",company_name:profile?.company_name||"",language:profile?.language||"fr"})},[profile]);useEffect(()=>{setA({display_name:account?.display_name||"",phone_number:account?.phone_number||"",phone_number_id:account?.phone_number_id||"",business_account_id:account?.business_account_id||"",status:account?.status||"pending"})},[account]);const saveProfile=async e=>{e.preventDefault();const r=await supabase.from("profiles").upsert({id:user.id,...p,updated_at:new Date().toISOString()});if(r.error)show(r.error.message,"error");else{setProfile({...profile,...p});show("Profil enregistré.")}};const saveAccount=async e=>{e.preventDefault();const payload={user_id:user.id,...a,updated_at:new Date().toISOString()};const r=account?await supabase.from("whatsapp_accounts").update(payload).eq("id",account.id).eq("user_id",user.id):await supabase.from("whatsapp_accounts").insert(payload).select("*").single();if(r.error){show(r.error.message,"error");return}setAccount(r.data||{...account,...payload});show("Configuration WhatsApp enregistrée.")};const metaUrl=import.meta.env.VITE_META_EMBEDDED_SIGNUP_URL||"";return <Page title="Paramètres" eyebrow="CONFIGURATION"><div className="settingsGrid"><div className="card settingsNav"><button className="selected">Profil</button><button onClick={()=>document.getElementById("whatsapp-settings")?.scrollIntoView({behavior:"smooth"})}>WhatsApp Business</button><button onClick={()=>show("La sécurité est assurée par Supabase Auth et les sessions persistantes.","success")}>Sécurité</button><button onClick={()=>show("Les notifications seront centralisées ici.","success")}>Notifications</button><button onClick={()=>document.getElementById("profile-language")?.focus()}>Langue</button></div><div><form className="card" onSubmit={saveProfile}><h3>Profil professionnel</h3><p>Informations de votre espace.</p><label className="field">Nom<input value={p.full_name} onChange={e=>setP({...p,full_name:e.target.value})} placeholder="Votre nom"/></label><label className="field">Entreprise<input value={p.company_name} onChange={e=>setP({...p,company_name:e.target.value})} placeholder="Nom de l’entreprise"/></label><label className="field">Langue<select id="profile-language" value={p.language} onChange={e=>setP({...p,language:e.target.value})}><option value="fr">Français</option><option value="en">English</option></select></label><button className="primary"><Save size={15}/> Enregistrer</button></form><form id="whatsapp-settings" className="card" style={{marginTop:14}} onSubmit={saveAccount}><div className="cardHead"><div><h3>WhatsApp Business</h3><p>Configuration de la connexion officielle de votre numéro.</p></div><span className={a.status==="connected"?"status connected":"status"}>{a.status==="connected"?"Connecté":"En attente"}</span></div>{metaUrl&&<button type="button" className="primary" style={{marginBottom:14}} onClick={()=>window.open(metaUrl,"_blank","noopener,noreferrer")}><ExternalLink size={15}/> Démarrer la connexion via Meta</button>}<div className="officialNote" style={{marginBottom:12}}><b>Parcours officiel</b><span>La connexion doit être réalisée avec les mécanismes prévus par Meta. Ne saisissez jamais votre token Meta dans cette page.</span></div><label className="field">Nom affiché<input value={a.display_name} onChange={e=>setA({...a,display_name:e.target.value})}/></label><label className="field">Numéro WhatsApp<input value={a.phone_number} onChange={e=>setA({...a,phone_number:e.target.value})} placeholder="+225..."/></label><label className="field">Phone Number ID<input value={a.phone_number_id} onChange={e=>setA({...a,phone_number_id:e.target.value})}/></label><label className="field">Business Account ID<input value={a.business_account_id} onChange={e=>setA({...a,business_account_id:e.target.value})}/></label><label className="field">Statut<select value={a.status} onChange={e=>setA({...a,status:e.target.value})}><option value="pending">En attente</option><option value="connected">Connecté</option><option value="disconnected">Déconnecté</option></select></label><button className="primary"><Save size={15}/> Enregistrer la connexion</button></form></div></div></Page>}

function TeamPortal({user,onLogout}){const[active,setActive]=useState("Vue générale");const[member,setMember]=useState(null);useEffect(()=>{(async()=>{const r=await supabase.from("team_members").select("*").eq("user_id",user.id).maybeSingle();if(!r.data&&user.email?.toLowerCase()==="admin@whatsendpro.app"){const x=await supabase.from("team_members").insert({user_id:user.id,role:"super_admin",active:true,must_change_password:true}).select("*").single();setMember(x.data)}else setMember(r.data)})()},[user]);if(!member||!member.active)return <div className="teamDenied"><div><Logo large/><h1>Accès refusé</h1><p>Ce compte n’est pas autorisé à accéder à l’espace équipe.</p><button className="primary" onClick={onLogout}>Se déconnecter</button></div></div>;if(member.must_change_password)return <TeamPasswordChange user={user} member={member} setMember={setMember} onLogout={onLogout}/>;const items=["Vue générale","Utilisateurs","WhatsApp","Abonnements","Facturation","Journal","Paramètres"];return <div className="teamApp"><aside className="teamSidebar"><Logo/><div className="teamPrivate">ESPACE INTERNE · {member.role}</div><nav>{items.map(x=><button className={active===x?"active":""} onClick={()=>setActive(x)} key={x}><span>•</span><div><b>{x}</b><small>Administration</small></div></button>)}</nav><button className="teamLogout" onClick={onLogout}><LogOut size={15}/> Déconnexion</button></aside><main className="teamMain"><header className="teamTopbar"><div><span>ADMINISTRATION</span><h1>{active}</h1></div><div className="teamUser"><span>Super administrateur</span><b>{user.email}</b></div></header><div className="teamContent">{active==="Vue générale"?<TeamOverview/>:<TeamSection title={active}/>}</div></main></div>}

function TeamPasswordChange({user,member,setMember,onLogout}){const[p,setP]=useState(""),[c,setC]=useState(""),[error,setError]=useState(""),save=async e=>{e.preventDefault();setError("");if(p.length<8)return setError("Minimum 8 caractères.");if(p!==c)return setError("Les mots de passe ne correspondent pas.");const r=await supabase.auth.updateUser({password:p});if(r.error)return setError(r.error.message);await supabase.from("team_members").update({must_change_password:false,updated_at:new Date().toISOString()}).eq("id",member.id);setMember({...member,must_change_password:false})};return <div className="teamAuthPage"><form className="teamAuthCard" onSubmit={save}><Logo large/><h1>Changer le mot de passe</h1><p>Un nouveau mot de passe est requis pour sécuriser l’accès interne.</p><label>Mot de passe<input type="password" value={p} onChange={e=>setP(e.target.value)} required/></label><label>Confirmation<input type="password" value={c} onChange={e=>setC(e.target.value)} required/></label>{error&&<div className="formError">{error}</div>}<button className="primary full">Enregistrer</button><button type="button" className="switchAuth" onClick={onLogout}>Déconnexion</button></form></div>}

function TeamOverview(){const[s,setS]=useState({users:0,contacts:0,messages:0,accounts:0});useEffect(()=>{(async()=>{const [u,c,m,a]=await Promise.all([supabase.from("profiles").select("id",{count:"exact",head:true}),supabase.from("contacts").select("id",{count:"exact",head:true}),supabase.from("messages").select("id",{count:"exact",head:true}),supabase.from("whatsapp_accounts").select("id",{count:"exact",head:true})]);setS({users:u.count||0,contacts:c.count||0,messages:m.count||0,accounts:a.count||0})})()},[]);return <><div className="teamWelcome"><div><span>SUPER ADMINISTRATEUR</span><h2>Centre de pilotage WhatSend Pro</h2><p>Supervision de la plateforme, des comptes et des connexions.</p></div><div className="teamStatus"><span className="greenDot"/> Système opérationnel</div></div><div className="teamStats">{[["Utilisateurs",s.users],["Contacts",s.contacts],["Messages",s.messages],["WhatsApp",s.accounts]].map(x=><div key={x[0]}><span>{x[0]}</span><strong>{x[1]}</strong><small>Données visibles</small></div>)}</div></>}

function TeamSection({title}){const d={Utilisateurs:"Gestion des comptes clients.",WhatsApp:"Supervision des connexions WhatsApp Business.",Abonnements:"Gestion des offres et accès.",Facturation:"Suivi des consommations et revenus.",Journal:"Journal des actions importantes.",Paramètres:"Configuration générale."};return <div className="teamEmpty"><b>{title}</b><span>{d[title]||"Module d’administration."}</span><button className="primary" onClick={()=>alert("Module disponible dans cette version d’administration.")}>Ouvrir le module</button></div>}

function AuthGate({mode,onAuth}){return <><Auth onAuth={onAuth} initialMode={mode}/><button className="backLanding" onClick={()=>go("/")}>← Retour à l’accueil</button></>}

function App(){
 const[user,setUser]=useState(null),[ready,setReady]=useState(!supabase),[route,setRoute]=useState(getPath()),[authMode,setAuthMode]=useState("login");
 useEffect(()=>{const path=()=>setRoute(getPath());window.addEventListener("popstate",path);if(!supabase){setReady(true);return()=>window.removeEventListener("popstate",path)}let live=true;(async()=>{const{data}=await supabase.auth.getSession();if(live){setUser(data.session?.user||null);setReady(true);if(data.session&&getPath()==="/auth/callback"){window.history.replaceState({},"","/dashboard");setRoute("/dashboard")}}})();const{data}=supabase.auth.onAuthStateChange((_e,s)=>{if(!live)return;setUser(s?.user||null);if(s?.user){const p=getPath();if(p==="/auth/callback"||p==="/login"||p==="/signup"||publicRoutes.includes(p)){window.history.replaceState({},"","/dashboard");setRoute("/dashboard")}}});return()=>{live=false;data.subscription.unsubscribe();window.removeEventListener("popstate",path)}},[]);
 const logout=async()=>{await supabase?.auth.signOut();setUser(null);go("/")};
 if(!ready)return <div className="loading">Chargement de votre espace…</div>;
 if(route.startsWith("/team"))return user?<TeamPortal user={user} onLogout={logout}/>:<><TeamLogin onAuth={setUser}/></>;
 if(user)return <Dashboard user={user} onLogout={logout}/>;
 if(route==="/login"||route==="/signup"||route==="/auth/callback")return <AuthGate mode={route==="/signup"?"signup":authMode} onAuth={setUser}/>;
 if(!publicRoutes.includes(route))return <AuthGate mode="login" onAuth={setUser}/>;
 return <Landing onAuth={m=>{setAuthMode(m);go(m==="signup"?"/signup":"/login")}}/>;
}

function TeamLogin({onAuth}){const[email,setEmail]=useState("admin@whatsendpro.app"),[password,setPassword]=useState(""),[error,setError]=useState(""),[loading,setLoading]=useState(false);const submit=async e=>{e.preventDefault();setError("");setLoading(true);const r=await supabase.auth.signInWithPassword({email:email.trim().toLowerCase(),password});setLoading(false);if(r.error)return setError("Identifiants incorrects ou accès équipe non autorisé.");onAuth(r.data.user)};return <div className="teamAuthPage"><div className="teamAuthCard"><Logo large/><span className="teamLabel">ESPACE ÉQUIPE · ACCÈS PRIVÉ</span><h1>Administration WhatSend Pro</h1><p>Cette interface est réservée à l’équipe interne.</p><form onSubmit={submit}><label>E-mail<input value={email} onChange={e=>setEmail(e.target.value)} type="email" required/></label><label>Mot de passe<input value={password} onChange={e=>setPassword(e.target.value)} type="password" required/></label>{error&&<div className="formError">{error}</div>}<button className="primary full" disabled={loading}>{loading?"Connexion…":"Accéder à l’administration"}</button></form><button className="teamBack" onClick={()=>go("/")}>← Retour au site public</button></div></div>}

createRoot(document.getElementById("root")).render(<App/>);
